// Is this job really from Scallle, and really for this workflow?
//
// The "Scallle job" trigger has already checked the token's signature and
// expiry (JWT Auth, with this automation's Scallle secret). This step checks
// the rest of the Scallle contract. Each reason is a plain sentence with no
// item data in it, because it goes back to Scallle.

// ---- Set these once per automation (README: "Set it up for a customer"). ----
// Where Scallle lives. Results are only ever sent back to this address.
const SCALLLE_ORIGIN = 'https://app.scallle.com';
// The one business (workspace), connection and automation this workflow works
// for, copied from Scallle. While any of them is blank, every job is refused,
// so a forgotten setup shows up in Scallle's test run.
const EXPECTED_WORKSPACE_ID = '';
const EXPECTED_CONNECTION_ID = '';
const EXPECTED_AUTOMATION_ID = '';
// ------------------------------------------------------------------------------

const FIVE_MINUTES_MS = 5 * 60 * 1000;

const job = $('Scallle job').first().json;
const token = job.jwtPayload || {};
const body = job.body || {};
const run = body.run || {};
// SHA-256 of the exact bytes n8n received, from "Fingerprint the body".
const receivedSha256 = $input.first().json.received_body_sha256;

const refuse = (reason) => [{ json: { genuine: false, reason } }];
const isText = (value) => typeof value === 'string' && value.length > 0;
// Ids go into the callback path below, so they must be plain ids.
const isId = (value) => typeof value === 'string' && /^[A-Za-z0-9_-]+$/.test(value);

if (!EXPECTED_WORKSPACE_ID || !EXPECTED_CONNECTION_ID || !EXPECTED_AUTOMATION_ID) {
  return refuse("This n8n workflow isn't set up yet: fill in the three EXPECTED_ ids at the top of its 'Check the job' step.");
}
if (token.iss !== 'scallle') {
  return refuse("The token wasn't issued by Scallle.");
}
// Scallle's tokens last 5 minutes. n8n checks that a token hasn't expired, but
// it also accepts one with no expiry, or one that lasts for days.
const nowSeconds = Date.now() / 1000;
if (!Number.isFinite(token.iat) || !Number.isFinite(token.exp) ||
    token.exp - token.iat > 300 || Math.abs(nowSeconds - token.iat) > 300) {
  return refuse("The token doesn't have Scallle's 5-minute lifetime.");
}
// Only trust what the body says once we know it is what Scallle signed.
if (!isText(token.body_sha256) || token.body_sha256.toLowerCase() !== receivedSha256) {
  return refuse('This job was changed after Scallle signed it.');
}
if (body.version !== 1) {
  return refuse('This workflow understands version 1 of the Scallle contract only.');
}
if (token.aud !== EXPECTED_CONNECTION_ID || body.connection_id !== EXPECTED_CONNECTION_ID) {
  return refuse('This job is for a different connection.');
}
if (run.workspace_id !== EXPECTED_WORKSPACE_ID) {
  return refuse('This job is for a different business.');
}
if (run.automation_id !== EXPECTED_AUTOMATION_ID) {
  return refuse('This job is for a different automation.');
}
if (!isId(run.id) || token.sub !== run.id) {
  return refuse('This job was signed for a different run.');
}
const issuedAt = Date.parse(body.issued_at);
if (!Number.isFinite(issuedAt) || Math.abs(Date.now() - issuedAt) > FIVE_MINUTES_MS) {
  return refuse('This job is more than 5 minutes old, or the clocks disagree.');
}

// The result goes back to this run's own callback on Scallle and nowhere else:
//   https://app.scallle.com/api/automations/<automation id>/runs/<run id>?token=...
// The Code node has no URL parser, so the address is matched exactly.
const callback = /^([a-z]+:\/\/[^/?#]+)(\/[^?#]*)(\?[^#]*)?$/.exec(String(body.callback && body.callback.url));
const expectedPath = '/api/automations/' + EXPECTED_AUTOMATION_ID + '/runs/' + run.id;
if (!callback || callback[1] !== SCALLLE_ORIGIN || callback[2] !== expectedPath) {
  return refuse("The callback address isn't this run's own address on Scallle.");
}

return [{ json: { genuine: true, reason: null } }];

// Turn Claude's answer into the result Scallle expects.
//
// Only the text of the answer goes back (thinking blocks are skipped). A
// refusal, a cut-off answer or an empty one is reported as a failure in one
// plain sentence, so a person picks the step up in Scallle.
//
// It reads the AI step by name, so app nodes that save the draft can go
// between "Do the work" and here. If you rename the AI step, rename it here.

const answer = $('Do the work').first().json;
const failed = (sentence) => [{ json: { status: 'error', error_message: sentence } }];

// Check why Claude stopped before reading what it wrote.
if (answer.stop_reason === 'refusal') {
  return failed('Claude declined to work on this item, so there is no result. Please do this step by hand.');
}
if (answer.stop_reason === 'max_tokens') {
  return failed("Claude's answer was cut off at the AI step's length limit. Ask for a shorter result in the step's procedure, or raise 'Maximum Number of Tokens' on the AI step in n8n a little.");
}

const text = (answer.content || [])
  .filter((block) => block.type === 'text')
  .map((block) => block.text)
  .join('')
  .trim();
if (!text) {
  return failed('Claude returned an empty answer, so there is no result. Please do this step by hand.');
}

const usage = answer.usage || {};
return [{
  json: {
    status: 'success',
    metadata: { result: text },
    // Lets Scallle cost the run.
    usage: {
      model: answer.model || null,
      input_tokens: usage.input_tokens ?? null,
      output_tokens: usage.output_tokens ?? null,
    },
  },
}];

// Say what went wrong in one plain sentence, for Scallle.
//
// The sentence is always one of the fixed ones below: n8n's own error text is
// never passed on, so no item data can reach Scallle this way. The full error
// stays on the failed step, in n8n's history of failed runs.
//
// Another step's error output can be wired here too (an Outlook or SharePoint
// node, say): Scallle is then told which step failed, by its name.

const failedStep = $prevNode.name;
const failed = (sentence) => [{ json: { status: 'error', error_message: sentence } }];

// The steps that make sure each run is worked once.
const CLAIM_STEPS = ['Claim this run', 'Find the first claim'];
if (CLAIM_STEPS.includes(failedStep)) {
  return failed("n8n couldn't check whether this run was already being worked (its 'Scallle run claims' data table), so the step wasn't done.");
}

// If you rename the AI step, rename it here too.
if (failedStep !== 'Do the work') {
  return failed("The '" + failedStep + "' step failed in n8n.");
}

const error = String($input.first().json.error || '');
return failed(
  /Authorization failed|Forbidden|credentials/i.test(error)
    ? "Anthropic refused the API key. Check the 'Anthropic — your own key' credential in n8n."
  : /too many requests/i.test(error)
    ? 'Anthropic is rate-limiting this API key. Please try the step again later.'
  : /could not be found/i.test(error)
    ? "Anthropic doesn't recognise the model named on the AI step. Check the model name in n8n."
  : /Bad request|invalid/i.test(error)
    ? "Anthropic rejected the request as invalid. Check the AI step's settings in n8n."
  : /service|gateway|unavailable|timed out|timeout|ECONN|ETIMEDOUT|socket|network/i.test(error)
    ? "Anthropic couldn't be reached or was overloaded. Please try the step again later."
  : 'The AI step failed in n8n.'
);
